import { MULTI, SINGLE_RANGES } from "./case-fold-table";

/**
 * Python's `str.casefold()`, as Home Assistant uses it to compare registry names. JavaScript has none:
 * `toLowerCase()` is a different mapping (ß, ς, ﬁ, Cherokee…) and applies final-sigma context on whole strings.
 * The table lists every code point casefold changes (generated by `scripts/gen-case-fold.py`); any other code point
 * is kept as is, so the result does not depend on the JavaScript engine's Unicode version.
 */
export function caseFold(s: string): string {
  let out = "";
  for (const ch of s) out += TABLE.get(ch.codePointAt(0) ?? 0) ?? ch;
  return out;
}

const TABLE: ReadonlyMap<number, string> = buildTable();

function buildTable(): Map<number, string> {
  const table = new Map<number, string>();
  for (const range of SINGLE_RANGES.split(";")) {
    const [start = 0, end = -1, step = 1, delta = 0] = range.split(",").map((v) => Number.parseInt(v, 16));
    for (let cp = start; cp <= end; cp += step) table.set(cp, String.fromCodePoint(cp + delta));
  }
  for (const entry of MULTI.split(";")) {
    const [cp = "", out = ""] = entry.split(":");
    table.set(Number.parseInt(cp, 16), String.fromCodePoint(...out.split(",").map((v) => Number.parseInt(v, 16))));
  }
  return table;
}
